/*
 * A343107  Numbers having exactly 1 divisor of the form 8*k + 1, that is,
 *          numbers with no divisor of the form 8*k + 1 other than 1.
 * https://oeis.org/A343107
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = the n‑th positive integer having no divisor congruent to
 *            1 modulo 8 other than 1. The sequence is generated by a sieve
 *            that marks all composite numbers with a divisor ≡ 1 (mod 8). The
 *            function keeps a static cache of the marked numbers and the list
 *            of "good" numbers, growing the cache unti...
 * Range:     u8 n <= 155, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

/* --- internal state --------------------------------------------------- */
static unsigned char *bad = NULL;       /* bad[i] = 1 if i has a divisor ≡1(mod8) */
static size_t        bad_len = 0;        /* size of 'bad' array       */

static seq_t *good = NULL;              /* list of good numbers      */
static size_t good_len = 0;             /* number of good numbers    */
static size_t good_cap = 0;             /* capacity of 'good' array  */

/* --------------------------------------------------------------------- */
static void rebuild_to_limit(size_t limit)
{
    /* Allocate / resize the bad array */
    unsigned char *tmp = (unsigned char *)realloc(bad, limit + 1);
    if (!tmp) abort();
    bad = tmp;
    bad_len = limit + 1;
    memset(bad, 0, bad_len);

    /* Mark multiples of every integer d ≡ 1 (mod 8), d > 1 */
    for (size_t d = 9; d <= limit; d += 8) {
        for (size_t m = d; m <= limit; m += d)
            bad[m] = 1;
    }

    /* Rebuild the list of good numbers */
    size_t new_cap = limit / 2 + 64;
    seq_t *tmp_good = (seq_t *)realloc(good, new_cap * sizeof(seq_t));
    if (!tmp_good) abort();
    good = tmp_good;
    good_cap = new_cap;
    good_len = 0;

    for (size_t i = 1; i <= limit; ++i) {
        if (!bad[i]) {
            if (good_len >= good_cap) {
                good_cap *= 2;
                seq_t *tmp2 = (seq_t *)realloc(good, good_cap * sizeof(seq_t));
                if (!tmp2) abort();
                good = tmp2;
            }
            good[good_len++] = (seq_t)i;
        }
    }
}

/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 0) /* sequence is 1‑based; index 0 is undefined */
        return 0;

    static size_t current_limit = 0;

    /* Ensure the cache contains at least n good numbers */
    while (good_len < (size_t)n) {
        size_t limit = (current_limit == 0) ? 64 : current_limit * 2;
        if (limit < (size_t)n) limit = (size_t)n;
        rebuild_to_limit(limit);
        current_limit = limit;
    }

    return good[(size_t)(n - 1)];
}
